proc decomposeCall(ctx: var Context, call: Atom, requireTopLevel: bool): (Atom, DecompositionStatus) {.nimcall.} =
  let empty = emptyList()
  if ctx.execution == nil or ctx.prepared == nil: return (empty, dsInvalidContext)
  let ex = ctx.execution
  ex.resetDiagnostics()
  if ctx.worldState == nil or ctx.bindings == nil: return (empty, dsInvalidContext)
  if not call.isKind(akList) or call.len < 1: return (empty, dsInvalidCall)
  let head = call.at(0)[0]
  if not head.isKind(akSymbol): return (empty, dsInvalidCall)
  let argumentCount = call.len - 1
  ex.begin(ctx, factSymbols, callNames)
  var entry = -1
  if entry < 0 and head.symbolValue == sym16 and argumentCount == 0:
    entry = 2
  if entry < 0: return (empty, dsInvalidCall)
  var runResult = 0
  case entry
  of 2:
    runResult = ex.run(method2)
  else: discard
  if runResult == 0: return (empty, ex.failureState)
  while ex.pendingCount != 0:
    let next = ex.popPending()
    if next == nil: break
    if ex.run(next) == 0: return (empty, ex.failureState)
  (ex.planAtom(), dsSucceeded)

